870	/**
871	 * In-process, typed publish/subscribe bus.
872	 *
873	 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
874	 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
875	 * every reactive concern `subscribe()`s at module init (see
876	 * `src/server/services/event-registry.ts`). Handlers are isolated — one
877	 * throwing handler never fails the emit or the sibling handlers.
878	 */
879	
880	type HandlerSet = Set<EventHandler<TaskflowEventType>>;
881	
882	const handlers = new Map<TaskflowEventType, HandlerSet>();
883	
884	const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();
885	
886	/** Registers a handler for one event type. Call the return value to detach. */
887	export function subscribe<K extends TaskflowEventType>(
888	  type: K,
889	  handler: EventHandler<K>,
890	): Unsubscribe {
891	  const set = handlers.get(type) ?? new Set();
892	  set.add(handler as EventHandler<TaskflowEventType>);
893	  handlers.set(type, set);
894	  return () => {
895	    set.delete(handler as EventHandler<TaskflowEventType>);
896	  };
897	}
898	
899	/** Registers a handler that detaches itself after the first delivery. */
900	export function subscribeOnce<K extends TaskflowEventType>(
901	  type: K,
902	  handler: EventHandler<K>,
903	): Unsubscribe {
904	  const off = subscribe(type, (payload) => {
905	    off();
906	    return handler(payload);
907	  });
908	  return off;
909	}
