935	/** Fire-and-forget variant for call sites that must not await delivery. */
936	export function emitAndForget<K extends TaskflowEventType>(
937	  type: K,
938	  payload: TaskflowEventPayload<K>,
939	): void {
940	  void emit(type, payload).catch((error: unknown) => {
941	    reportHandlerError(type, error);
942	  });
943	}
