949	  return () => {
950	    errorSinks.delete(sink);
951	  };
952	}
953	
954	function reportHandlerError(type: TaskflowEventType, error: unknown): void {
955	  for (const sink of errorSinks) {
956	    try {
957	      sink(type, error);
958	    } catch {
959	      // A failing error sink must never escalate.
960	    }
961	  }
962	}
