83	/** Fields present on every event payload; the bus stamps them on `emit`. */
84	export interface EventEnvelope {
85	  readonly orgId: OrgId;
86	  readonly actorId: UserId | null;
87	  readonly occurredAt: IsoTimestamp;
88	}
