90	/**
91	 * The complete catalogue of domain events. `emit()` and `subscribe()` in
92	 * `src/lib/event-bus.ts` are keyed on this map, so adding an event here is the
93	 * only way to introduce one — services, jobs and the webhook dispatcher all
94	 * derive their handler signatures from it.
95	 */
96	export interface TaskflowEventMap {
97	  "project.created": EventEnvelope & {
98	    projectId: ProjectId;
99	    name: string;
100	    slug: string;
101	  };
102	  "project.archived": EventEnvelope & {
103	    projectId: ProjectId;
104	    issuesArchived: number;
105	  };
106	  "project.restored": EventEnvelope & { projectId: ProjectId };
107	  "issue.created": EventEnvelope & {
108	    issueId: IssueId;
109	    projectId: ProjectId;
110	    title: string;
111	    assigneeId: UserId | null;
112	    priority: IssuePriority;
113	  };
114	  "issue.updated": EventEnvelope & {
115	    issueId: IssueId;
116	    projectId: ProjectId;
117	    changedFields: readonly string[];
118	  };
119	  "issue.status_changed": EventEnvelope & {
120	    issueId: IssueId;
121	    projectId: ProjectId;
122	    from: IssueStatus;
123	    to: IssueStatus;
124	  };
125	  "issue.assigned": EventEnvelope & {
126	    issueId: IssueId;
127	    projectId: ProjectId;
128	    previousAssigneeId: UserId | null;
129	    assigneeId: UserId;
130	  };
131	  "issue.archived": EventEnvelope & { issueId: IssueId; projectId: ProjectId };
132	  "issue.overdue": EventEnvelope & {
133	    issueId: IssueId;
134	    projectId: ProjectId;
135	    dueAt: IsoTimestamp;
136	    assigneeId: UserId | null;
137	  };
138	  "comment.created": EventEnvelope & {
139	    commentId: CommentId;
140	    issueId: IssueId;
141	    mentionedUserIds: readonly UserId[];
142	  };
143	  "comment.deleted": EventEnvelope & { commentId: CommentId; issueId: IssueId };
144	  "member.invited": EventEnvelope & { email: string; role: Role };
145	  "member.joined": EventEnvelope & { memberId: MemberId; userId: UserId; role: Role };
146	  "member.role_changed": EventEnvelope & {
147	    memberId: MemberId;
148	    from: Role;
149	    to: Role;
150	  };
151	  "member.removed": EventEnvelope & { memberId: MemberId; userId: UserId };
152	  "billing.plan_changed": EventEnvelope & { from: PlanId; to: PlanId };
153	  "billing.limit_exceeded": EventEnvelope & {
154	    resource: LimitedResource;
155	    limit: number;
156	    used: number;
157	  };
158	  "flag.toggled": EventEnvelope & { flag: FeatureFlagKey; enabled: boolean };
159	  "digest.due": EventEnvelope & { recipientId: UserId; windowStart: IsoTimestamp };
160	  "search.reindex_requested": EventEnvelope & {
161	    subjectKind: "issue" | "comment" | "project";
162	    subjectId: string;
163	  };
164	  "webhook.delivery_requested": EventEnvelope & {
165	    eventType: string;
166	    payload: Readonly<Record<string, unknown>>;
167	  };
168	}
