175	/** A handler registered with `subscribe()`. May be async; errors are isolated. */
176	export type EventHandler<K extends TaskflowEventType> = (
177	  payload: TaskflowEventPayload<K>,
178	) => void | Promise<void>;
179	
180	/** Returned by `subscribe()`; calling it removes the handler. */
181	export type Unsubscribe = () => void;
