324	 * an event handler running outside a request, and the row's `actorId` comes
325	 * from the event payload rather than from an authenticated principal.
326	 */
327	export async function record(
328	  orgId: OrgId,
329	  action: ActivityAction,
330	  input: ActivityRecordInput,
331	): Promise<ActivityEvent> {
332	  return activityRepo.insertActivity({
333	    orgId,
