354	/** Groups a feed page by calendar day, newest day first. */
355	export function groupByDay(
356	  events: readonly ActivityEvent[],
357	): readonly ActivityGroup[] {
358	  const byDay = new Map<string, ActivityEvent[]>();
359	
360	  for (const event of events) {
361	    const day = event.occurredAt.slice(0, 10);
362	    const bucket = byDay.get(day) ?? [];
363	    bucket.push(event);
364	    byDay.set(day, bucket);
365	  }
366	
367	  return [...byDay.entries()]
368	    .sort(([a], [b]) => (a < b ? 1 : -1))
369	    .map(([day, dayEvents]) => ({ day, events: dayEvents }));
370	}
