558	export async function listActivity(
559	  input: ActivityFilterInput,
560	): Promise<Page<ActivityEvent>> {
561	  const db = getDb();
562	  const sort = {
563	    sortColumn: activityEvents.occurredAt,
564	    idColumn: activityEvents.id,
565	  };
566	
567	  const filters = compact(
568	    orgPredicate(activityEvents.orgId, input.orgId),
569	    input.action === undefined || input.action.length === 0
570	      ? undefined
571	      : inArray(activityEvents.action, [...input.action]),
572	    input.actorId === undefined
573	      ? undefined
574	      : eq(activityEvents.actorId, input.actorId),
575	    input.projectId === undefined
576	      ? undefined
577	      : eq(activityEvents.projectId, input.projectId),
578	    input.subjectKind === undefined
579	      ? undefined
580	      : eq(activityEvents.subjectKind, input.subjectKind),
581	    input.since === undefined
582	      ? undefined
583	      : gte(activityEvents.occurredAt, input.since),
584	    // Half-open on the right so consecutive windows tile without overlap:
585	    // [since, until) followed by [until, next).
586	    input.until === undefined
587	      ? undefined
588	      : lt(activityEvents.occurredAt, input.until),
589	  );
590	
591	  const total = db
592	    .select({ value: count() })
593	    .from(activityEvents)
594	    .where(and(...filters))
595	    .get();
596	
597	  const rows = db
598	    .select()
599	    .from(activityEvents)
600	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
601	    .orderBy(desc(activityEvents.occurredAt), desc(activityEvents.id))
602	    .limit(probeLimit(input.limit))
603	    .all();
604	
605	  return toPage(
606	    rows,
607	    input.limit,
608	    total?.value ?? 0,
609	    toActivityEvent,
610	    (row) => ({ id: row.id, sortValue: row.occurredAt }),
611	  );
612	}
