911	/**
912	 * Publishes an event to every subscriber. Resolves once all handlers settle;
913	 * rejected handlers are reported to the error sinks, never rethrown.
914	 */
915	export async function emit<K extends TaskflowEventType>(
916	  type: K,
917	  payload: TaskflowEventPayload<K>,
918	): Promise<void> {
919	  const set = handlers.get(type);
920	  if (!set || set.size === 0) return;
921	
922	  const results = await Promise.allSettled(
923	    [...set].map(async (handler) => {
924	      await (handler as EventHandler<K>)(payload);
925	    }),
926	  );
927	
928	  for (const result of results) {
929	    if (result.status === "rejected") {
930	      reportHandlerError(type, result.reason);
931	    }
932	  }
933	}
