977	 * Private paging helpers shared by the repositories in this directory.
978	 *
979	 * Not part of the public data-access surface — repositories re-export nothing
980	 * from here. Keyset (cursor) pagination is expressed as a row-value comparison
981	 * so a page boundary is stable even when two rows share a `created_at`.
982	 */
983	import { sql } from "drizzle-orm";
984	import { decodeCursor, encodeCursor } from "./base-repository";
985	import { makePage } from "@/types/common";
986	import type { Page } from "@/types/common";
987	import type { SQL } from "drizzle-orm";
988	import type { SQLiteColumn } from "drizzle-orm/sqlite-core";
989	
990	export interface KeysetSort {
991	  readonly sortColumn: SQLiteColumn;
992	  readonly idColumn: SQLiteColumn;
993	}
994	
995	/**
996	 * Predicate that resumes a descending listing after `cursor`. Returns
997	 * `undefined` for a first page or an unparseable cursor — a bad cursor
998	 * degrades to "start from the top", never to an error page.
999	 */
1000	export function keysetPredicate(
1001	  sort: KeysetSort,
1002	  cursor: string | null | undefined,
1003	): SQL | undefined {
1004	  if (!cursor) return undefined;
1005	  const decoded = decodeCursor(cursor);
1006	  if (!decoded) return undefined;
1007	
1008	  return sql`(${sort.sortColumn}, ${sort.idColumn}) < (${decoded.sortValue}, ${decoded.id})`;
1009	}
1010	
1011	/** SQLite tolerates a `LIMIT` of `n + 1`; that extra row is the has-more probe. */
1012	export function probeLimit(limit: number): number {
1013	  return Math.max(1, Math.min(limit, 100)) + 1;
1014	}
1015	
1016	/**
1017	 * Turns an over-fetched row array into a `Page`, dropping the probe row and
1018	 * deriving the next cursor from the last row that survived.
1019	 */
1020	export function toPage<TRow, TOut>(
1021	  rows: readonly TRow[],
1022	  limit: number,
1023	  total: number,
1024	  map: (row: TRow) => TOut,
1025	  cursorOf: (row: TRow) => { id: string; sortValue: string },
1026	): Page<TOut> {
1027	  const capped = Math.max(1, Math.min(limit, 100));
1028	  const hasMore = rows.length > capped;
1029	  const visible = hasMore ? rows.slice(0, capped) : rows;
1030	  const last = visible.at(-1);
1031	
1032	  const nextCursor =
1033	    hasMore && last
1034	      ? encodeCursor(cursorOf(last).id, cursorOf(last).sortValue)
1035	      : null;
1036	
1037	  return makePage(visible.map(map), nextCursor, total);
1038	}
1039	
1040	/** Drops the `undefined` slots so `and(...)` never sees a hole. */
1041	export function compact(
1042	  ...predicates: readonly (SQL | undefined)[]
1043	): readonly SQL[] {
1044	  return predicates.filter((value): value is SQL => value !== undefined);
1045	}
