 * from the event payload rather than from an authenticated principal.
 *
 * `occurredAt` is when the action happened — the event's own stamp — not when
 * the row is written; a job that catches up later still files it correctly.
 */
export async function record(
  orgId: OrgId,
  action: ActivityAction,
  input: ActivityRecordInput,
): Promise<ActivityEvent> {
  return activityRepo.insertActivity({
    orgId,
    action,
    actorId: input.actorId,
    subjectKind: input.subjectKind,
    subjectId: input.subjectId,
    projectId: input.projectId,
    summary: input.summary,
    metadata: input.metadata ?? {},
    occurredAt: happenedAt(input.occurredAt),
  });
}

function happenedAt(value: IsoTimestamp | undefined): IsoTimestamp {
  if (value !== undefined && !Number.isNaN(new Date(value).getTime())) {
    return toIsoTimestamp(value);
  }
  return toIsoTimestamp(new Date());
}

/** Refuses a range that ends before it starts; equal ends are a valid instant. */
function assertOrderedRange(since?: string, until?: string): void {
  if (since === undefined || until === undefined) return;
  if (new Date(since).getTime() > new Date(until).getTime()) {
    throw new ZodError([
      {
        code: "custom",
        path: ["until"],
        message: "until must not be earlier than since",
        input: until,
      },
    ]);
  }
}

export async function listActivity(
  actor: Actor,
  input: ActivityFilterInput,
): Promise<Page<ActivityEvent>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "activity:read", activityResource(input.orgId));
  assertOrderedRange(input.since, input.until);
  return activityRepo.listActivity(input);
}

